const CHROMA_ANCHOR_GLYPHS={"dew":"<path d=\"M32 8C28 21 17 28 17 39a15 15 0 0 0 30 0C47 28 36 20 32 8Z\"/><path d=\"M23 38c0 7 3 10 9 11\"/>","ripple":"<circle cx=\"32\" cy=\"32\" r=\"18\"/><circle cx=\"32\" cy=\"32\" r=\"10\"/><path d=\"m32 25 7 7-7 7-7-7Z\"/>","bloom":"<ellipse cx=\"32\" cy=\"22\" rx=\"6\" ry=\"11\" transform=\"rotate(0 32 32)\"/><ellipse cx=\"32\" cy=\"22\" rx=\"6\" ry=\"11\" transform=\"rotate(60 32 32)\"/><ellipse cx=\"32\" cy=\"22\" rx=\"6\" ry=\"11\" transform=\"rotate(120 32 32)\"/><ellipse cx=\"32\" cy=\"22\" rx=\"6\" ry=\"11\" transform=\"rotate(180 32 32)\"/><ellipse cx=\"32\" cy=\"22\" rx=\"6\" ry=\"11\" transform=\"rotate(240 32 32)\"/><ellipse cx=\"32\" cy=\"22\" rx=\"6\" ry=\"11\" transform=\"rotate(300 32 32)\"/><circle cx=\"32\" cy=\"32\" r=\"5\"/>","frost":"<path d=\"M32 32V10m0 9-6-5m6 5 6-5\" transform=\"rotate(0 32 32)\"/><path d=\"M32 32V10m0 9-6-5m6 5 6-5\" transform=\"rotate(60 32 32)\"/><path d=\"M32 32V10m0 9-6-5m6 5 6-5\" transform=\"rotate(120 32 32)\"/><path d=\"M32 32V10m0 9-6-5m6 5 6-5\" transform=\"rotate(180 32 32)\"/><path d=\"M32 32V10m0 9-6-5m6 5 6-5\" transform=\"rotate(240 32 32)\"/><path d=\"M32 32V10m0 9-6-5m6 5 6-5\" transform=\"rotate(300 32 32)\"/><circle cx=\"32\" cy=\"32\" r=\"4\"/>","stellar":"<path d=\"m32 11 5 15 16 6-16 5-5 16-5-16-16-5 16-6Z\"/><circle cx=\"32\" cy=\"32\" r=\"4\"/>","inferno":"<path d=\"M35 7c4 16 17 21 15 34a18 18 0 0 1-36-1c-1-8 4-16 12-22-1 9 2 12 5 14 5-8 7-14 4-25Z\"/><path d=\"M33 33c-2 8-9 9-8 16a7 7 0 0 0 14-1c0-6-6-8-6-15Z\"/>","crown":"<path d=\"m11 21 10 8 11-16 11 16 10-8-6 25H17Z\"/><path d=\"M18 51h28M21 38h22m-11-9 4 5-4 5-4-5Z\"/><circle cx=\"11\" cy=\"18\" r=\"2\"/><circle cx=\"53\" cy=\"18\" r=\"2\"/>","cosmos":"<path d=\"m32 16 4 12 12 4-12 4-4 12-4-12-12-4 12-4Z\"/><circle cx=\"32\" cy=\"32\" r=\"21\"/><path d=\"M14 49h36M20 55h24\"/>"};
let chromaOpening=false,chromaColorOpen=false;
function openChromaTutorial(){location.assign('/chroma/tutorial?returnTo='+encodeURIComponent(room?'/?room='+room.code:'/?game=chroma'));}
function chromaAnchorEntry(){
 const p=me(),profile=room.chromaProfile;if(!p||!profile)return '';const item=room.chromaAnchors?.find(a=>a.id===profile.equipped),art=item?'<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round">'+CHROMA_ANCHOR_GLYPHS[item.id]+'</svg>':'◇';
 return '<div class="chroma-anchor-entry"><div class="chroma-anchor-art" style="color:'+p.chromaColor+'">'+art+'</div><div><strong>图案 · 个人锚点</strong><small>'+esc(item?item.name+' · 已佩戴':'当前未佩戴')+'</small><small>✦ '+profile.coins+' 桌游币</small></div><button class="outline full" type="button" data-chroma-anchors>进入锚点藏馆</button></div>';
}
function chromaColorPicker(){
 const p=me(),palette=room.chromaPalette||[];if(!p||!palette.length)return '';
 const selected=palette.find(c=>c.color===p.chromaColor);
 return '<details class="chroma-color-picker" '+(chromaColorOpen?'open':'')+'><summary><i style="background:'+p.chromaColor+'"></i>玩家颜色：'+esc(selected?.name||'系统分配')+'</summary><p>36 色可选 · 已占用的颜色不可选 · 开局后锁定</p><button type="button" class="outline full" data-chroma-color="default">'+(p.chromaColorChoice?'恢复默认分配':'✓ 默认分配中')+'</button><div class="chroma-color-grid" role="group" aria-label="选择玩家颜色">'+palette.map(c=>{const other=room.players.find(q=>q.id!==p.id&&q.chromaColor===c.color),chosen=p.chromaColor===c.color;return '<button type="button" data-chroma-color="'+c.color+'" class="'+(chosen?'chosen':'')+'" aria-pressed="'+chosen+'" title="'+esc(c.name+' · '+c.color+(other?' · '+other.name+'正在使用':''))+'" aria-label="'+esc(c.name+'，'+c.color+(other?'，'+other.name+'正在使用':''))+'" '+(other?'disabled':'')+'><i style="background:'+c.color+'"></i><small>'+esc(c.name)+'</small><span>'+(other?'×':chosen?'✓':'')+'</span></button>';}).join('')+'</div></details>';
}
function chromaWaiting(){return '<p>游戏提供者：ww</p>'+chromaAnchorEntry()+chromaColorPicker()+'<button class="outline full" type="button" data-chroma-tutorial>进入新手教学局</button><p>原版 11 步实操教学 · 不改变当前房间与对局</p>'+(room.hostId===playerId?'<div class="chroma-options"><label>对局轮数<select id="chromaRounds">'+[6,10,15].map(n=>'<option value="'+n+'" '+((room.chromaSettings?.rounds||10)===n?'selected':'')+'>'+n+' 轮</option>').join('')+'</select></label><label>强化间隔<select id="chromaAugmentEvery">'+[2,3,5].map(n=>'<option value="'+n+'" '+((room.chromaSettings?.augmentEvery||3)===n?'selected':'')+'>每 '+n+' 轮</option>').join('')+'</select></label></div>':'<p>本桌 '+(room.chromaSettings?.rounds||10)+' 轮，每 '+(room.chromaSettings?.augmentEvery||3)+' 轮选择强化。</p>');}
function renderChroma(){if(chromaOpening)return;chromaOpening=true;location.replace('/chroma/play?room='+encodeURIComponent(room.code));}
document.addEventListener('change',e=>{if(['chromaRounds','chromaAugmentEvery'].includes(e.target.id))action('chromaSettings',{rounds:Number($('chromaRounds').value),augmentEvery:Number($('chromaAugmentEvery').value)});});
document.addEventListener('click',e=>{if(e.target.closest('[data-chroma-anchors]'))location.assign('/chroma/anchors?room='+encodeURIComponent(room.code));if(e.target.closest('[data-chroma-tutorial]'))openChromaTutorial();const color=e.target.closest('[data-chroma-color]');if(color&&!color.disabled)action('chromaColor',{color:color.dataset.chromaColor==='default'?null:color.dataset.chromaColor});});

document.addEventListener('toggle',e=>{if(e.target.classList?.contains('chroma-color-picker'))chromaColorOpen=e.target.open;},true);
